		INTERVIEW_NO
		, PROCESS_NO
		, INTERVIEW_DATE
		, INTERVIEW_LOCATION
		, INTERVIEW_TYPE
		, INTERVIEW_PASS_SCORE
	) VALUES (
		#{interviewNo}
